using System;using System.Linq;using System.Reflection;using Unity.Entities;using Unity.Jobs;using Unity.Mathematics;using Unity.Collections;using Game.Components;
namespace Unity.Entities {public static class SourceGroundMissileChunkSchedule {public static JobHandle ScheduleParallel<T>(this T job,EntityQuery query,JobHandle dependency)where T:struct,IJobChunk {if(typeof(T).FullName!="Game.Runtime.GroundMissileProjectileFlightSystem+ProjectileFlightJob"||!ReferenceEquals(query.Manager,SystemAPI.Manager))throw new NotSupportedException("Exact original projectile job/same source manager required");dependency.Complete();var desc=query.Description;if(!desc.HasValue||desc.Value.All.Length!=2||!desc.Value.All.Select(c=>c.Type).OrderBy(t=>t.FullName).SequenceEqual(new[]{typeof(GroundMissileProjectileComponent),typeof(Unity.Transforms.LocalTransform)}.OrderBy(t=>t.FullName)))throw new NotSupportedException("Original projectile query changed");var rows=query.Current;if(rows.Length>65536)throw new NotSupportedException("Source projectile job entity bound");var chunk=new ArchetypeChunk{SourceMissileChunk=true,Manager=query.Manager,Entities=rows,Count=rows.Length};object boxed=job;try{typeof(T).GetMethod("Execute").Invoke(boxed,new object[]{chunk,0,false,default(Unity.Burst.Intrinsics.v128)});}catch(TargetInvocationException e){throw e.InnerException??e;}return default;}}}
namespace Game.Runtime {internal static class SourceMissileTrailPresentationBoundary {internal static long RequestedSyncs;internal static void Sync(Entity projectile,float3 position,float3 direction){if(!math.all(math.isfinite(position))||!math.all(math.isfinite(direction)))throw new NotSupportedException("Finite original trail request required");RequestedSyncs=checked(RequestedSyncs+1);/* Presentation-only request observed; no GameObject/renderer is created, no simulation state is written. */}}}


